#!/usr/bin/env python3
"""Graph update for the 2026-09-17 MORNING brief (Day 202).
Backup: backups/2026-09-17/graph_v1
Sources: staging/2026-09-17-morning/{intel,markets}.md
Run ONCE, capture output to a file.
"""
import json, os

D = "2026-09-17"
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NODES = os.path.join(ROOT, "graph", "nodes")
log = []


def _load(nid):
    p = os.path.join(NODES, nid + ".json")
    if not os.path.exists(p):
        log.append(("MISSING", nid)); return None, None
    return json.load(open(p)), p


def _save(d, p):
    json.dump(d, open(p, "w"), indent=1, ensure_ascii=False)


def sig(nid, headline):
    d, p = _load(nid)
    if d is None: return
    d.setdefault("recent_signals", []).insert(0, {"date": D, "headline": headline})
    d["last_updated"] = D; _save(d, p); log.append(("SIG", nid))


def current(nid, **kw):
    d, p = _load(nid)
    if d is None: return
    d.setdefault("current", {}).update(kw); d["last_updated"] = D
    _save(d, p); log.append(("CUR", nid))


def summary(nid, text):
    d, p = _load(nid)
    if d is None: return
    d["summary"] = text; d["last_updated"] = D; _save(d, p); log.append(("SUM", nid))


def snapshot(nid, price, trigger):
    d, p = _load(nid)
    if d is None: return
    d.setdefault("price_snapshots", []).append({"date": D, "price": price, "trigger": trigger})
    d["last_updated"] = D; _save(d, p); log.append(("SNAP", nid))


def trig_set(nid, match, status, note):
    d, p = _load(nid)
    if d is None: return
    hits = [t for t in d.get("active_triggers", []) if match.lower() in str(t.get("condition", "")).lower()]
    if len(hits) != 1:
        log.append(("TRIG-AMBIG", nid, match, len(hits))); return
    t = hits[0]
    prior = t.get("notes", "")
    if t.get("status") != status:
        t["status_changed"] = D
    t["status"] = status
    t["notes"] = note + ("\n[prior] " + prior[:400] if prior else "")
    d["last_updated"] = D; _save(d, p); log.append(("TRIG", nid, match[:30], status))


def trig_note(nid, match, note):
    """Reviewed, status unchanged."""
    d, p = _load(nid)
    if d is None: return
    hits = [t for t in d.get("active_triggers", []) if match.lower() in str(t.get("condition", "")).lower()]
    if len(hits) != 1:
        log.append(("TRIG-AMBIG", nid, match, len(hits))); return
    t = hits[0]; prior = t.get("notes", "")
    t["notes"] = note + ("\n[prior] " + prior[:300] if prior else "")
    d["last_updated"] = D; _save(d, p); log.append(("TRIG-REV", nid, match[:30], t.get("status")))


def trig_add(nid, condition, status, cascade, note):
    d, p = _load(nid)
    if d is None: return
    if any(str(t.get("condition", "")).lower()[:55] == condition.lower()[:55] for t in d.get("active_triggers", [])):
        log.append(("TRIG-DUP", nid)); return
    d.setdefault("active_triggers", []).append(
        {"condition": condition, "status": status, "cascade": cascade, "added": D, "notes": note})
    d["last_updated"] = D; _save(d, p); log.append(("TRIG-NEW", nid))


